import{_ as a,o as n,c as e,ag as l}from"./chunks/framework.1IVNT0ce.js";const F=JSON.parse('{"title":"Getting Started","description":"","frontmatter":{},"headers":[],"relativePath":"getting-started.md","filePath":"getting-started.md"}'),o={name:"getting-started.md"};function t(p,s,c,r,i,d){return n(),e("div",null,[...s[0]||(s[0]=[l(`<h1 id="getting-started" tabindex="-1">Getting Started <a class="header-anchor" href="#getting-started" aria-label="Permalink to &quot;Getting Started&quot;">​</a></h1><p>This page gives you the shortest realistic path from install to a working Klix app.</p><p>If you want a more hands-on walkthrough, continue to <a href="./quickstart">Quickstart</a>. If you want to understand the model first, read <a href="./concepts/architecture">Architecture</a>.</p><h2 id="the-mental-model" tabindex="-1">The Mental Model <a class="header-anchor" href="#the-mental-model" aria-label="Permalink to &quot;The Mental Model&quot;">​</a></h2><p>Klix applications are built around a few core objects:</p><ul><li><code>App</code> defines the application and owns the runtime</li><li><code>Session</code> represents one terminal instance</li><li><code>Command</code> objects define slash commands</li><li><code>session.ui</code> is where rendering and interactive widgets live</li></ul><p>The default runtime loop is command-driven:</p><ol><li>start the app</li><li>read a line of input</li><li>parse it as a slash command</li><li>run middleware</li><li>invoke the handler</li></ol><p>That design is covered in <a href="./concepts/app">App</a>, <a href="./concepts/commands">Commands</a>, and <a href="./concepts/router">Router</a>.</p><h2 id="smallest-useful-app" tabindex="-1">Smallest Useful App <a class="header-anchor" href="#smallest-useful-app" aria-label="Permalink to &quot;Smallest Useful App&quot;">​</a></h2><p>Create <code>main.py</code>:</p><div class="language-python"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki material-theme-palenight vp-code" tabindex="0"><code><span class="line"><span style="color:#89DDFF;font-style:italic;">import</span><span style="color:#BABED8;"> klix</span></span>
<span class="line"></span>
<span class="line"><span style="color:#BABED8;">app </span><span style="color:#89DDFF;">=</span><span style="color:#BABED8;"> klix</span><span style="color:#89DDFF;">.</span><span style="color:#82AAFF;">App</span><span style="color:#89DDFF;">(</span></span>
<span class="line"><span style="color:#BABED8;font-style:italic;">    name</span><span style="color:#89DDFF;">=</span><span style="color:#89DDFF;">&quot;</span><span style="color:#C3E88D;">mytool</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">,</span></span>
<span class="line"><span style="color:#BABED8;font-style:italic;">    version</span><span style="color:#89DDFF;">=</span><span style="color:#89DDFF;">&quot;</span><span style="color:#C3E88D;">0.1.0</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">,</span></span>
<span class="line"><span style="color:#BABED8;font-style:italic;">    description</span><span style="color:#89DDFF;">=</span><span style="color:#89DDFF;">&quot;</span><span style="color:#C3E88D;">A simple Klix app</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">,</span></span>
<span class="line"><span style="color:#89DDFF;">)</span></span>
<span class="line"></span>
<span class="line"><span style="color:#89DDFF;">@</span><span style="color:#82AAFF;">app</span><span style="color:#89DDFF;">.</span><span style="color:#82AAFF;">on</span><span style="color:#89DDFF;">(</span><span style="color:#89DDFF;">&quot;</span><span style="color:#C3E88D;">start</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">)</span></span>
<span class="line"><span style="color:#C792EA;">def</span><span style="color:#82AAFF;"> on_start</span><span style="color:#89DDFF;">(</span><span style="color:#BABED8;font-style:italic;">session</span><span style="color:#89DDFF;">:</span><span style="color:#BABED8;"> klix</span><span style="color:#89DDFF;">.</span><span style="color:#F07178;">Session</span><span style="color:#89DDFF;">):</span></span>
<span class="line"><span style="color:#BABED8;">    session</span><span style="color:#89DDFF;">.</span><span style="color:#F07178;">ui</span><span style="color:#89DDFF;">.</span><span style="color:#82AAFF;">print</span><span style="color:#89DDFF;">(</span><span style="color:#89DDFF;">&quot;</span><span style="color:#C3E88D;">Ready.</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">,</span><span style="color:#BABED8;font-style:italic;"> color</span><span style="color:#89DDFF;">=</span><span style="color:#89DDFF;">&quot;</span><span style="color:#C3E88D;">accent</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">,</span><span style="color:#BABED8;font-style:italic;"> bold</span><span style="color:#89DDFF;">=True)</span></span>
<span class="line"></span>
<span class="line"><span style="color:#89DDFF;">@</span><span style="color:#82AAFF;">app</span><span style="color:#89DDFF;">.</span><span style="color:#82AAFF;">command</span><span style="color:#89DDFF;">(</span><span style="color:#89DDFF;">&quot;</span><span style="color:#C3E88D;">/hello</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">,</span><span style="color:#BABED8;font-style:italic;"> help</span><span style="color:#89DDFF;">=</span><span style="color:#89DDFF;">&quot;</span><span style="color:#C3E88D;">Say hello</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">)</span></span>
<span class="line"><span style="color:#C792EA;">def</span><span style="color:#82AAFF;"> hello</span><span style="color:#89DDFF;">(</span><span style="color:#BABED8;font-style:italic;">session</span><span style="color:#89DDFF;">:</span><span style="color:#BABED8;"> klix</span><span style="color:#89DDFF;">.</span><span style="color:#F07178;">Session</span><span style="color:#89DDFF;">):</span></span>
<span class="line"><span style="color:#BABED8;">    session</span><span style="color:#89DDFF;">.</span><span style="color:#F07178;">ui</span><span style="color:#89DDFF;">.</span><span style="color:#82AAFF;">print</span><span style="color:#89DDFF;">(</span><span style="color:#89DDFF;">&quot;</span><span style="color:#C3E88D;">Hello from Klix.</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">,</span><span style="color:#BABED8;font-style:italic;"> color</span><span style="color:#89DDFF;">=</span><span style="color:#89DDFF;">&quot;</span><span style="color:#C3E88D;">success</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">)</span></span>
<span class="line"></span>
<span class="line"><span style="color:#89DDFF;font-style:italic;">if</span><span style="color:#BABED8;"> __name__ </span><span style="color:#89DDFF;">==</span><span style="color:#89DDFF;"> &quot;</span><span style="color:#C3E88D;">__main__</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">:</span></span>
<span class="line"><span style="color:#BABED8;">    app</span><span style="color:#89DDFF;">.</span><span style="color:#82AAFF;">run</span><span style="color:#89DDFF;">()</span></span></code></pre></div><p>Run it:</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki material-theme-palenight vp-code" tabindex="0"><code><span class="line"><span style="color:#FFCB6B;">python</span><span style="color:#C3E88D;"> main.py</span></span></code></pre></div><p>Then type:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki material-theme-palenight vp-code" tabindex="0"><code><span class="line"><span>/hello</span></span></code></pre></div><h2 id="what-happened" tabindex="-1">What Happened <a class="header-anchor" href="#what-happened" aria-label="Permalink to &quot;What Happened&quot;">​</a></h2><ul><li><code>App(...)</code> created the command registry and runtime configuration</li><li><code>@app.on(&quot;start&quot;)</code> registered a lifecycle hook</li><li><code>@app.command(...)</code> created and registered a <code>Command</code></li><li><code>app.run()</code> started the event loop and interactive session</li></ul><p>See:</p><ul><li><a href="./concepts/app">App</a></li><li><a href="./concepts/events">Events</a></li><li><a href="./concepts/commands">Commands</a></li></ul><h2 id="using-the-scaffold-instead" tabindex="-1">Using The Scaffold Instead <a class="header-anchor" href="#using-the-scaffold-instead" aria-label="Permalink to &quot;Using The Scaffold Instead&quot;">​</a></h2><p>If you want a generated starting point instead of writing the app by hand:</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki material-theme-palenight vp-code" tabindex="0"><code><span class="line"><span style="color:#FFCB6B;">klix</span><span style="color:#C3E88D;"> init</span><span style="color:#C3E88D;"> mytool</span></span>
<span class="line"><span style="color:#82AAFF;">cd</span><span style="color:#C3E88D;"> mytool</span></span>
<span class="line"><span style="color:#FFCB6B;">pip</span><span style="color:#C3E88D;"> install</span><span style="color:#C3E88D;"> -e</span><span style="color:#C3E88D;"> .</span></span>
<span class="line"><span style="color:#FFCB6B;">mytool</span></span></code></pre></div><p>The generated project includes:</p><ul><li>a working <code>App</code></li><li>a typed state class</li><li>one event handler</li><li>one middleware example</li><li>one command with <code>args_schema</code></li></ul><p>See <a href="./guides/building-your-first-cli">Building Your First CLI</a>.</p><h2 id="where-to-go-next" tabindex="-1">Where To Go Next <a class="header-anchor" href="#where-to-go-next" aria-label="Permalink to &quot;Where To Go Next&quot;">​</a></h2><ul><li>Learn the runtime model in <a href="./concepts/architecture">Architecture</a></li><li>Learn command design in <a href="./guides/adding-commands">Adding Commands</a></li><li>Learn UI rendering in <a href="./guides/creating-ui">Creating UI</a></li><li>Learn persistence in <a href="./guides/persistence">Persistence</a></li></ul>`,28)])])}const y=a(o,[["render",t]]);export{F as __pageData,y as default};
